text:
Lab: live Boolean operators


Lab · live data from OpenAlex

Type two concepts (you can use OR, quotation marks and truncation within each one) and press Search. The book queries OpenAlex, an open index of more than 250 million scholarly works, and shows how many documents each combination retrieves. Watch how AND reduces, OR broadens and NOT excludes.

viewof consulta = {
  const f = html`&lt;form class="lab-form"&gt;
    &lt;div class="row g-2"&gt;
      &lt;div class="col-md-5"&gt;&lt;label class="form-label" for="lab-a"&gt;Concept A&lt;/label&gt;
        &lt;input id="lab-a" name="a" class="form-control form-control-sm" value='smartphone OR "mobile phone"'&gt;&lt;/div&gt;
      &lt;div class="col-md-5"&gt;&lt;label class="form-label" for="lab-b"&gt;Concept B&lt;/label&gt;
        &lt;input id="lab-b" name="b" class="form-control form-control-sm" value='"academic performance"'&gt;&lt;/div&gt;
      &lt;div class="col-md-2 d-flex align-items-end"&gt;&lt;button class="btn btn-primary btn-sm w-100" type="submit"&gt;Search&lt;/button&gt;&lt;/div&gt;
    &lt;/div&gt;&lt;/form&gt;`;
  f.value = {a: f.a.value, b: f.b.value};
  f.onsubmit = e =&gt; { e.preventDefault(); f.value = {a: f.a.value.trim(), b: f.b.value.trim()}; f.dispatchEvent(new Event("input", {bubbles: true})); };
  return f;
}







recuentos = {
  const q = s =&gt; fetch("https://api.openalex.org/works?per-page=1&search=" + encodeURIComponent(s))
    .then(r =&gt; { if (!r.ok) throw new Error(r.status); return r.json(); }).then(j =&gt; j.meta.count);
  const A = `(${consulta.a})`, B = `(${consulta.b})`;
  yield {cargando: true};
  try {
    const [a, b, y, o, n] = await Promise.all([q(A), q(B), q(`${A} AND ${B}`), q(`${A} OR ${B}`), q(`${A} NOT ${B}`)]);
    yield {a, b, y, o, n};
  } catch (e) { yield {error: true}; }
}







{
  if (recuentos.cargando) return html`&lt;p role="status"&gt;Querying OpenAlex…&lt;/p&gt;`;
  if (recuentos.error) return html`&lt;p role="status"&gt;OpenAlex could not be reached (are you offline?). Try again later.&lt;/p&gt;`;
  const filas = [["A", recuentos.a], ["B", recuentos.b], ["A AND B", recuentos.y], ["A OR B", recuentos.o], ["A NOT B", recuentos.n]];
  const max = Math.max(...filas.map(f =&gt; f[1]), 1);
  const fmt = new Intl.NumberFormat("en-GB");
  return html`&lt;table class="table table-sm lab-tabla" role="status"&gt;
    &lt;caption&gt;Documents in OpenAlex for each combination&lt;/caption&gt;
    &lt;thead&gt;&lt;tr&gt;&lt;th scope="col"&gt;Search&lt;/th&gt;&lt;th scope="col"&gt;Documents&lt;/th&gt;&lt;th scope="col"&gt;&lt;span class="visually-hidden"&gt;Bar&lt;/span&gt;&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;
    &lt;tbody&gt;${filas.map(([k, v]) =&gt; html`&lt;tr&gt;&lt;th scope="row"&gt;&lt;code&gt;${k}&lt;/code&gt;&lt;/th&gt;&lt;td style="text-align:right"&gt;${fmt.format(v)}&lt;/td&gt;
      &lt;td style="width:50%"&gt;&lt;div style="height:.8rem;border-radius:2px;background:#2a78d6;width:${Math.max(1, 100 * v / max)}%"&gt;&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;`)}&lt;/tbody&gt;&lt;/table&gt;
    &lt;p&gt;Check: &lt;code&gt;A OR B&lt;/code&gt; = &lt;code&gt;A&lt;/code&gt; + &lt;code&gt;B&lt;/code&gt; − &lt;code&gt;A AND B&lt;/code&gt;
    (${fmt.format(recuentos.a + recuentos.b - recuentos.y)} versus ${fmt.format(recuentos.o)}; any difference is due to the search engine).&lt;/p&gt;`;
}






Try: add a synonym to A with OR and see how A AND B changes; then put a phrase in quotation marks and compare it with the same words without them.

Lab: what a similarity checker sees


Lab · runs in your browser, without sending the text anywhere

Paste an original text and your version. The lab splits both into groups of three words (trigrams), calculates what proportion they share (Jaccard similarity) and highlights the words in your version that belong to copied trigrams. Try a verbatim copy, a patchwriting and a real paraphrase.

texto = window.Lab.texto
area = window.Lab.area
seleccion = window.Lab.seleccion
rango = window.Lab.rango
boton = window.Lab.boton





































viewof original = area("Original text", {rows: 4, value: "Lateral reading means leaving the page to check what other sources say about it and about what it claims."})
viewof version = area("Your version", {rows: 4, value: "Lateral reading means leaving the website to check what other sources say about it and about what it claims."})
















{
  const palabras = t =&gt; t.toLowerCase().normalize("NFC").replace(/[^\p{L}\p{N}\s]/gu, " ").split(/\s+/).filter(Boolean);
  const tri = p =&gt; { const s = new Set(); for (let i = 0; i + 2 &lt; p.length; i++) s.add(p.slice(i, i + 3).join(" ")); return s; };
  const pa = palabras(original), pb = palabras(version), ta = tri(pa), tb = tri(pb);
  const comunes = [...tb].filter(x =&gt; ta.has(x));
  const union = new Set([...ta, ...tb]);
  const j = union.size ? comunes.length / union.size : 0;
  const marcadas = new Array(pb.length).fill(false);
  for (let i = 0; i + 2 &lt; pb.length; i++) if (ta.has(pb.slice(i, i + 3).join(" "))) { marcadas[i] = marcadas[i + 1] = marcadas[i + 2] = true; }
  const veredicto = j &gt;= 0.8 ? "almost a verbatim copy" : j &gt;= 0.25 ? "many overlaps: possible patchwriting" : j &gt; 0 ? "few overlaps" : "no three-word overlaps";
  return html`&lt;div role="status"&gt;
    &lt;p&gt;&lt;strong&gt;Similarity: ${(100 * j).toFixed(0)}%&lt;/strong&gt; (${comunes.length} shared trigrams out of ${union.size} distinct) · ${veredicto}.&lt;/p&gt;
    ${(() =&gt; { const p = document.createElement("p"); p.className = "lab-resaltado"; pb.forEach((w, i) =&gt; { if (i) p.append(" "); if (marcadas[i]) { const m = document.createElement("mark"); m.textContent = w; p.append(m); } else p.append(w); }); return p; })()}
    &lt;p class="small"&gt;Remember: a low similarity does &lt;em&gt;not&lt;/em&gt; prove there is no plagiarism (an uncited paraphrase or translation is plagiarism), and a high one does not prove it either if the fragment is quoted.&lt;/p&gt;&lt;/div&gt;`;
}

Lab: from DOI to reference


Lab · live data from Crossref

Type a DOI and the lab asks Crossref for the reference in APA 7, just as a reference manager does. Then check it: look for extra capital letters, missing italics or incomplete data. This is exactly what Gilmour & Cobus-Kuo (2011) found.

texto = window.Lab.texto
area = window.Lab.area
seleccion = window.Lab.seleccion
rango = window.Lab.rango
boton = window.Lab.boton





































viewof doi = texto("DOI", {value: "10.1016/j.pragma.2013.07.012", submit: "Get the reference"})







referencia = {
  const limpio = doi.trim().replace(/^https?:\/\/(dx\.)?doi\.org\//i, "").replace(/^doi:\s*/i, "");
  if (!/^10\.\d{4,9}\/\S+$/.test(limpio)) { yield {aviso: "That does not look like a DOI: DOIs start with \"10.\" followed by a prefix and a slash."}; return; }
  yield {cargando: true};
  try {
    const r = await fetch(`https://api.crossref.org/v1/works/${encodeURIComponent(limpio)}/transform`, {headers: {Accept: "text/x-bibliography; style=apa"}});
    if (r.status === 404) { yield {aviso: "Crossref does not know that DOI. It may belong to another agency (DataCite, for example) or not exist: check it at https://doi.org/" + limpio}; return; }
    yield {texto: (await r.text()).trim(), doi: limpio};
  } catch (e) { yield {aviso: "Crossref could not be reached (are you offline?)."}; }
}







referencia.cargando ? html`&lt;p role="status"&gt;Querying Crossref…&lt;/p&gt;` :
referencia.aviso ? html`&lt;p role="status"&gt;${referencia.aviso}&lt;/p&gt;` :
html`&lt;div role="status"&gt;&lt;p&gt;&lt;strong&gt;Generated reference:&lt;/strong&gt;&lt;/p&gt;&lt;blockquote class="lab-cita"&gt;${referencia.texto}&lt;/blockquote&gt;
&lt;p class="small"&gt;What would you correct? In APA, the article title is in sentence case (capital only for the first word and proper nouns), and the journal and volume are in italics (the formatting is lost here).&lt;/p&gt;&lt;/div&gt;`






Also try: 10.1108/eb024320, 10.1038/s41598-023-41032-5 or the DOI of the Spanish edition of this book, 10.5281/zenodo.24515144 (registered with DataCite, not Crossref).

Lab: a miniature language model


Lab · runs in your browser

This toy model has “read” only a dozen sentences about libraries and information. For each word it counts which words follow it and how often (a bigram model). Choose a starting word and the temperature: with low temperature it almost always picks the most likely word; with high temperature it takes more risks. Generate several sentences: you will see fluent and plausible texts, some of them false. Large models are vastly more complex, but they share this idea: predicting what comes next, not checking the truth.

texto = window.Lab.texto
area = window.Lab.area
seleccion = window.Lab.seleccion
rango = window.Lab.rango
boton = window.Lab.boton





































corpus = `the library offers books and journals to students .
the library offers access to scientific databases .
students search for articles in databases .
students cite the articles with their reference .
the reference includes the author and the year of the article .
the author of the article publishes in a scientific journal .
a scientific journal reviews the articles by peers .
the reviewed articles offer reliable information .
reliable information cites its sources .
disinformation imitates reliable information .
students verify the information in several sources .
the library catalogue offers books and articles .`
modelo = {
  const m = new Map();
  for (const f of corpus.split("\n")) {
    const p = f.trim().split(/\s+/);
    for (let i = 0; i + 1 &lt; p.length; i++) {
      if (!m.has(p[i])) m.set(p[i], new Map());
      const s = m.get(p[i]); s.set(p[i + 1], (s.get(p[i + 1]) || 0) + 1);
    }
  }
  return m;
}
viewof inicio = seleccion("Starting word", [...modelo.keys()].filter(w =&gt; w !== ".").sort((a, b) =&gt; a.localeCompare(b, "en")), {value: "the"})
viewof temperatura = rango("Temperature", [0.1, 2], {step: 0.1, value: 1})
viewof generar = boton("Generate another sentence")





































probs = (w, t) =&gt; {
  const s = modelo.get(w); if (!s) return [];
  const pares = [...s.entries()], pesos = pares.map(([, c]) =&gt; Math.pow(c, 1 / t)), z = pesos.reduce((a, b) =&gt; a + b, 0);
  return pares.map(([p], i) =&gt; [p, pesos[i] / z]).sort((a, b) =&gt; b[1] - a[1]);
}
frase = {
  generar;
  const out = [inicio]; let w = inicio;
  for (let k = 0; k &lt; 18 && w !== "."; k++) {
    const ps = probs(w, temperatura); if (!ps.length) break;
    let r = Math.random(), acc = 0, elegido = ps[ps.length - 1][0];
    for (const [p, q] of ps) { acc += q; if (r &lt;= acc) { elegido = p; break; } }
    out.push(elegido); w = elegido;
  }
  return out.join(" ").replace(" .", ".");
}
html`&lt;div role="status"&gt;&lt;p&gt;&lt;strong&gt;Generated sentence:&lt;/strong&gt; "${frase}"&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What can follow "${inicio}"&lt;/strong&gt; at temperature ${temperatura}:&lt;/p&gt;
&lt;table class="table table-sm"&gt;&lt;thead&gt;&lt;tr&gt;&lt;th scope="col"&gt;Next word&lt;/th&gt;&lt;th scope="col"&gt;Probability&lt;/th&gt;&lt;th scope="col"&gt;&lt;span class="visually-hidden"&gt;Bar&lt;/span&gt;&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;&lt;tbody&gt;
${probs(inicio, temperatura).slice(0, 6).map(([p, q]) =&gt; html`&lt;tr&gt;&lt;td&gt;${p}&lt;/td&gt;&lt;td&gt;${(100 * q).toFixed(0)}%&lt;/td&gt;&lt;td style="width:50%"&gt;&lt;div style="height:.8rem;border-radius:2px;background:#2a78d6;width:${100 * q}%"&gt;&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;`)}
&lt;/tbody&gt;&lt;/table&gt;&lt;/div&gt;`






















Try: generate sentences from “the” at temperature 2. Do any of them claim something the corpus does not say? That is, on a small scale, a hallucination.

Lab: verifying references


Lab · live data from doi.org and Crossref

Paste the DOIs an AI has given you (one per line; the full link also works). The lab checks at doi.org whether each DOI exists and, if it is registered with Crossref, retrieves the title and year so you can check that they match what the AI told you.

viewof lista = area("DOIs (one per line)", {rows: 5, submit: "Verify",
  value: "10.1038/s41598-023-41032-5\n10.1016/j.ipm.2019.102041\n10.1093/jis/abc123\nhttps://doi.org/10.1145/3442188.3445922"})







verificacion = {
  const dois = lista.split(/\n+/).map(x =&gt; x.trim().replace(/^https?:\/\/(dx\.)?doi\.org\//i, "").replace(/^doi:\s*/i, "")).filter(Boolean).slice(0, 20);
  yield {cargando: true};
  const uno = async d =&gt; {
    if (!/^10\.\d{4,9}\/\S+$/.test(d)) return {d, estado: "formato", texto: "Not in DOI format."};
    try {
      const h = await (await fetch("https://doi.org/api/handles/" + encodeURI(d))).json();
      if (h.responseCode !== 1) return {d, estado: "no", texto: "Does not exist at doi.org."};
      try {
        const r = await fetch("https://api.crossref.org/works/" + encodeURIComponent(d));
        if (r.ok) { const m = (await r.json()).message;
          const anio = (m.issued?.["date-parts"]?.[0]?.[0]) ?? "n.d.";
          return {d, estado: "si", texto: `${(m.title || [""])[0]} (${anio}). ${(m["container-title"] || [""])[0]}`}; }
      } catch (e) {}
      return {d, estado: "si", texto: "Exists (registered outside Crossref, for example with DataCite)."};
    } catch (e) { return {d, estado: "error", texto: "Could not be checked (offline?)."}; }
  };
  yield {filas: await Promise.all(dois.map(uno))};
}







verificacion.cargando ? html`&lt;p role="status"&gt;Verifying…&lt;/p&gt;` : html`&lt;table class="table table-sm" role="status"&gt;
&lt;caption&gt;${verificacion.filas.filter(f =&gt; f.estado === "si").length} of ${verificacion.filas.length} DOIs exist&lt;/caption&gt;
&lt;thead&gt;&lt;tr&gt;&lt;th scope="col"&gt;DOI&lt;/th&gt;&lt;th scope="col"&gt;Exists?&lt;/th&gt;&lt;th scope="col"&gt;What the record says&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;&lt;tbody&gt;
${verificacion.filas.map(f =&gt; html`&lt;tr&gt;&lt;td&gt;&lt;code&gt;${f.d}&lt;/code&gt;&lt;/td&gt;&lt;td&gt;${f.estado === "si" ? "✓ Yes" : f.estado === "no" ? "✗ No" : "?"}&lt;/td&gt;&lt;td&gt;${f.texto}&lt;/td&gt;&lt;/tr&gt;`)}
&lt;/tbody&gt;&lt;/table&gt;`






A DOI that exists is not enough: check that the title, authors and year match the reference the AI gave you. Walters & Wilder (2023) found, as well as fabricated references, many real references with errors in their details.

Lab: review your prompt


Lab · runs in your browser · sends nothing to any AI

A good prompt usually gives context, a specific task, the format of the answer, limits and a request for verification. Write yours: the lab looks for those pieces by keywords and suggests what to add. It is a rough guide, not a mark.

areaP = window.Lab.area
viewof prompt = areaP("Your prompt", {rows: 5, value: "Give me a summary of climate change."})
















{
  const t = prompt.toLowerCase();
  const piezas = [
    ["Context", /\b(i am|i'm|i study|for (a|an|my)|course|degree|module|assignment|level|aimed at|audience)\b/, "Say who you are and what you need it for: \"I am a first-year journalism student preparing a 5-minute presentation\"."],
    ["Specific task", /\b(summari[sz]e|summary|explain|compare|list|identify|classify|propose|review|correct|translate|analy[sz]e|draft|write)\b/, "Use a precise action verb: summarise, compare, classify…"],
    ["Format", /\b(table|list|bullet|bullets|paragraph|paragraphs|words|lines|outline|sections|points)\b|\d+\s*(words|lines|points|ideas)/, "State the format and length: \"in a three-column table\", \"in 150 words\"."],
    ["Limits or sources", /\b(only|without|do not invent|don't invent|based on|from the text|according to|attached|since 20\d\d)\b/, "Set limits: \"based only on the text I paste\", \"without inventing data\"."],
    ["Verification", /\b(cite|sources|references|doi|tell me (if|when)|not sure|uncertain|uncertainty|check|verify)\b/, "Ask it to say where each fact comes from and what it does not know: \"give your sources and tell me if you are not sure\"."]];
  const res = piezas.map(([n, re, consejo]) =&gt; [n, re.test(t), consejo]);
  const ok = res.filter((r) =&gt; r[1]).length;
  const d = html`&lt;div role="status" aria-live="polite"&gt;&lt;/div&gt;`;
  d.innerHTML = `&lt;p&gt;&lt;strong&gt;${ok} of 5 pieces&lt;/strong&gt; detected.&lt;/p&gt;&lt;ul class="list-unstyled"&gt;${res.map(([n, o, c]) =&gt; `&lt;li class="mb-1"&gt;${o ? "✓" : "○"} &lt;strong&gt;${n}&lt;/strong&gt;${o ? "" : ` — ${c}`}&lt;/li&gt;`).join("")}&lt;/ul&gt;${ok &gt;= 4 ? "&lt;p&gt;A good prompt. Remember: even with a good prompt, verify what the AI answers (section 5).&lt;/p&gt;" : ""}`;
  return d;
}






Try to improve the example prompt until it has all five pieces and compare it with the one in example 2.

Lab: evaluate a source with the CRAAP test


Lab · runs in your browser

The CRAAP test, created at the Meriam Library of California State University, Chico, evaluates a source with five criteria. Score a source you are using (from 0 to 10) and look at its profile.

rangoC = window.Lab.rango
viewof cActualidad = rangoC("Currency: is it recent enough for your topic? Is it updated?", [0, 10], {value: 7})
viewof cRelevancia = rangoC("Relevance: does it answer your question at the right level?", [0, 10], {value: 8})
viewof cAutoridad = rangoC("Authority: who signs it? Do they have credentials and an affiliation?", [0, 10], {value: 4})
viewof cExactitud = rangoC("Accuracy: does it provide evidence and verifiable sources? Has it been reviewed?", [0, 10], {value: 3})
viewof cProposito = rangoC("Purpose: does it inform, sell, persuade or entertain?", [0, 10], {value: 5})












































{
  const crit = [["Currency", cActualidad], ["Relevance", cRelevancia], ["Authority", cAutoridad], ["Accuracy", cExactitud], ["Purpose", cProposito]];
  const total = crit.reduce((s, c) =&gt; s + c[1], 0);
  const peor = [...crit].sort((a, b) =&gt; a[1] - b[1])[0];
  const barras = crit.map(([n, v], i) =&gt; `&lt;g transform="translate(0 ${i * 34})"&gt;&lt;text x="0" y="20" font-size="14" fill="currentColor"&gt;${n}&lt;/text&gt;&lt;rect x="110" y="6" width="300" height="20" rx="4" fill="var(--bs-secondary-bg)"/&gt;&lt;rect x="110" y="6" width="${v * 30}" height="20" rx="4" fill="${v &lt; 5 ? "#b3261e" : "#1c6b3a"}"/&gt;&lt;text x="${118 + v * 30}" y="21" font-size="13" fill="currentColor"&gt;${v}${v &lt; 5 ? " ⚠" : ""}&lt;/text&gt;&lt;/g&gt;`).join("");
  const veredicto = total &gt;= 40 && peor[1] &gt;= 5 ? "A solid source: you can use it, citing it correctly." : total &gt;= 25 ? `Use it with caution and check it against other sources. Its weak point is ${peor[0].toLowerCase()}.` : "An unreliable source: find a better one before using it.";
  const d = html`&lt;div role="status" aria-live="polite"&gt;&lt;/div&gt;`;
  d.innerHTML = `&lt;svg viewBox="0 0 460 172" width="100%" style="max-width:520px" role="img" aria-label="CRAAP profile: ${crit.map(([n, v]) =&gt; n + " " + v).join(", ")}" font-family="inherit"&gt;${barras}&lt;/svg&gt;&lt;p&gt;&lt;strong&gt;Total: ${total} out of 50.&lt;/strong&gt; ${veredicto}&lt;/p&gt;${peor[0] === "Accuracy" || peor[0] === "Authority" ? '&lt;p class="small"&gt;Tip: apply &lt;strong&gt;lateral reading&lt;/strong&gt; (open other tabs and search for what others say about the source) before reading on.&lt;/p&gt;' : ""}`;
  return d;
}






Criteria below 5 are marked with ⚠. A high score does not replace critical judgement: the test is a guide, not a formula.

Lab: misleading charts


Lab · runs in your browser

The same data can tell different stories depending on how they are drawn. These are a library’s (fictitious) monthly loans. Change the chart’s design decisions and see how much loans appear to grow.

casG = window.Lab.casilla
selG = window.Lab.seleccion
viewof cero = casG("The vertical axis starts at 0", {value: true})
viewof periodo = selG("Period shown", ["The whole year", "Only the last 3 months"], {value: "The whole year"})






























{
  const meses = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
  const v = [1180, 1215, 1240, 1195, 1160, 980, 640, 610, 1120, 1190, 1205, 1260];
  const ini = periodo.startsWith("Only") ? 9 : 0;
  const m = meses.slice(ini), d = v.slice(ini);
  const ymin = cero ? 0 : Math.min(...d) - 20, ymax = Math.max(...d) + 20;
  const W = 520, H = 240, bw = (W - 60) / d.length;
  const y = (x) =&gt; H - 30 - (x - ymin) / (ymax - ymin) * (H - 50);
  let svg = `&lt;svg viewBox="0 0 ${W} ${H}" width="100%" style="max-width:560px" role="img" aria-label="Bar chart of loans from ${m[0]} to ${m[m.length - 1]}; the axis starts at ${Math.round(ymin)}" font-family="inherit"&gt;`;
  [ymin, (ymin + ymax) / 2, ymax].forEach((t) =&gt; svg += `&lt;line x1="44" x2="${W - 10}" y1="${y(t)}" y2="${y(t)}" stroke="currentColor" stroke-opacity="0.15"/&gt;&lt;text x="40" y="${y(t) + 4}" font-size="11" text-anchor="end" fill="currentColor"&gt;${Math.round(t)}&lt;/text&gt;`);
  d.forEach((x, i) =&gt; svg += `&lt;rect x="${50 + i * bw + 3}" y="${y(x)}" width="${bw - 6}" height="${H - 30 - y(x)}" fill="#2a78d6" rx="3"/&gt;&lt;text x="${50 + i * bw + bw / 2}" y="${H - 12}" font-size="11" text-anchor="middle" fill="currentColor"&gt;${m[i]}&lt;/text&gt;`);
  svg += "&lt;/svg&gt;";
  const primero = d[0], ultimo = d[d.length - 1];
  const real = (ultimo - primero) / primero * 100;
  const visual = ((H - 30 - y(ultimo)) - (H - 30 - y(primero))) / (H - 30 - y(primero)) * 100;
  const f = (x) =&gt; (x &gt; 0 ? "+" : "") + x.toFixed(0) + "%";
  const msgs = [];
  if (!cero) msgs.push("The truncated axis turns a small difference into a huge one: compare the height of the bars with the numbers on the axis.");
  if (ini &gt; 0) msgs.push("Showing only three months hides the summer drop and the context of the year: it is cherry picking.");
  const dd = html`&lt;div role="status" aria-live="polite"&gt;&lt;/div&gt;`;
  dd.innerHTML = `${svg}&lt;p&gt;From &lt;strong&gt;${m[0]}&lt;/strong&gt; to &lt;strong&gt;${m[m.length - 1]}&lt;/strong&gt; loans change by &lt;strong&gt;${f(real)}&lt;/strong&gt;, but the bar grows by &lt;strong&gt;${f(visual)}&lt;/strong&gt;${Math.abs(visual - real) &gt; 10 ? " ⚠" : ""}.&lt;/p&gt;${msgs.length ? `&lt;ul&gt;${msgs.map((x) =&gt; `&lt;li&gt;${x}&lt;/li&gt;`).join("")}&lt;/ul&gt;` : "&lt;p&gt;With the axis starting at 0 and the full period, the height of the bars is proportional to the data.&lt;/p&gt;"}`;
  return dd;
}






In bar charts the axis must start at 0, because we compare lengths. In line charts the axis can be narrowed if this is clearly indicated, because we compare slopes.
